                for c0 in range(w):
                    for c1 in range(c0, w):
                        area = (r1-r0+1)*(c1-c0+1)
                        if area < 8:
                            continue
                        count = sum(grid[r][c] == color
                                    for r in range(r0, r1+1)
                                    for c in range(c0, c1+1))
                        if count / area >= 0.68:
                            valid.append((r0,r1,c0,c1))
        # Keep only inclusion-maximal rectangles, so each complete object is retained.
        maximal = []
        for rect in valid:
            a,b,c,d = rect
            if not any(x <= a and y >= b and z <= c and t >= d and (x,y,z,t) != rect
                       for x,y,z,t in valid):
                maximal.append(rect)
        for r0,r1,c0,c1 in maximal:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    result[r][c] = color
    return result

